// Local-presence area codes per state pool (primary first). Extend as pools open.
const AREA = {
  AL:['205','251'], AK:['907'], AZ:['602','480'], AR:['501','479'], CA:['213','415','619'],
  CO:['303','719'], CT:['203','860'], DE:['302'], FL:['305','407','813'], GA:['404','678'],
  HI:['808'], ID:['208'], IL:['312','773'], IN:['317'], IA:['515'], KS:['316','913'],
  KY:['502','859'], LA:['504','225'], ME:['207'], MD:['410','301'], MA:['617','508'],
  MI:['313','616'], MN:['612','651'], MS:['601'], MO:['314','816'], MT:['406'], NE:['402'],
  NV:['702','775'], NH:['603'], NJ:['201','732'], NM:['505'], NY:['212','718','516'],
  NC:['704','919'], ND:['701'], OH:['614','216'], OK:['405','918'], OR:['503'],
  PA:['215','412'], RI:['401'], SC:['803','843'], SD:['605'], TN:['615','901'],
  // TX order: 469/972/817 verified in-stock via live API 2026-07-26; 214 was dry.
  TX:['469','972','817','214','512','713'], UT:['801'], VT:['802'], VA:['703','804'], WA:['206','253'],
  WV:['304'], WI:['414','608'], WY:['307']
};
const b = $json.body ?? $json;
const state = String(b.state || '').toUpperCase().trim();
const codes = AREA[state] || [];
// Random seat password meeting GHL's policy (verified live 2026-07-26:
// upper + lower + digit + special required, else 422). Rep resets on first login.
const pick = (s) => s[crypto.getRandomValues(new Uint32Array(1))[0] % s.length];
const CH = 'ABCDEFGHJKMNPQRSTUVWXYZabcdefghjkmnpqrstuvwxyz23456789!@#$%^&*';
const pw = pick('ABCDEFGHJKMNPQRSTUVWXYZ') + pick('abcdefghjkmnpqrstuvwxyz') + pick('23456789') + pick('!@#$%^&*')
  + Array.from(crypto.getRandomValues(new Uint32Array(14)), n => CH[n % CH.length]).join('');
return [{ json: {
  first_name: b.first_name, last_name: b.last_name || '', email: b.email,
  phone: b.phone || '', state, partner_code: b.partner_code || '',
  area_primary: codes[0] || '', area_fallbacks: codes.slice(1), seat_password: pw,
}}];

// Pre-purchase gate: the partner must hold a live claim on the exact
// state we're about to buy a number for. Anything else aborts BEFORE
// the purchase step — an unclaimed/mismatched state never spends money.
const prep = $('Prep — Area Codes + Seat Password').first().json;
const claim = $json.data ?? $json;
const held = String(claim.assignedState || '').toUpperCase();
if (!held) {
  throw new Error(`ABORT: partner ${prep.partner_code} has no claimed state in WeShare — assign one (admin → assign_state) before provisioning.`);
}
if (held !== prep.state) {
  throw new Error(`ABORT: webhook asked for ${prep.state} but partner ${prep.partner_code} holds ${held}. No number purchased.`);
}
return [{ json: prep }];

// Pick the first available number; surface a clear error if the area code is dry.
const prep = $('Prep — Area Codes + Seat Password').first().json;
const list = $json.numbers ?? $json.data ?? (Array.isArray($json) ? $json : []);
const pick = Array.isArray(list) && list.length ? (list[0].phoneNumber ?? list[0].number ?? list[0]) : null;
if (!pick) {
  throw new Error(`No local numbers available for area code ${prep.area_primary} (state ${prep.state}). Re-run with a fallback code: ${prep.area_fallbacks.join(', ') || 'none mapped'} — or buy manually in Settings → Phone Numbers.`);
}
return [{ json: { ...prep, chosen_number: typeof pick === 'string' ? pick : String(pick) } }];

// Trust, then verify — against the GRANULAR scope layer (authoritative)
// AND the legacy flags. Template = verbatim copy of the live Demo User.
const u = $json.user ?? $json;
const perms = u.permissions ?? {};
const scopes = new Set(u.scopes ?? []);
const DEMO = ["askai.write", "calendars.readonly", "calendars/events.write", "contacts.write", "conversations.readonly", "conversations.write", "conversations/message.readonly", "conversations/message.write", "copilot.readonly", "dashboard/stats.readonly", "native-integrations.readonly", "native-integrations.write", "opportunities.write", "opportunities/leadValue.readonly", "prospecting.readonly", "prospecting.write", "prospecting/reports.readonly", "reporting/agent.readonly", "reporting/phone.readonly"];
const bad = [];
for (const s of DEMO) if (!scopes.has(s)) bad.push(`missing scope ${s}`);
for (const s of scopes) if (!DEMO.includes(s)) bad.push(`unexpected scope ${s}`);
for (const s of scopes) if (s.toLowerCase().includes('affiliate')) bad.push(`AFFILIATE SCOPE PRESENT: ${s}`);
const ado = u.scopesAssignedToOnly ?? [];
for (const s of ["calendars.readonly", "contacts.write", "opportunities.write"]) if (!ado.includes(s)) bad.push(`assigned-only missing ${s}`);
if (perms.affiliateManagerEnabled === true) bad.push('legacy affiliateManagerEnabled true');
if (perms.assignedDataOnly !== true) bad.push('legacy assignedDataOnly not true');
const role = u.roles?.role ?? u.role;
if (role && role !== 'user') bad.push(`role should be user, got ${role}`);
if (bad.length) throw new Error('SEAT LOCKDOWN VERIFY FAILED — do NOT hand out credentials: ' + bad.join(' | '));
const prep = $('Pick Number').first().json;
return [{ json: { ...prep, seat_user_id: u.id, seat_verified: true } }];

